                    continue

                new_val = min(j + amount, target)
                if dp[j] + cost < dp[new_val]:
                    dp[new_val] = dp[j] + cost

        return dp[target]

    # Maximum possible k is N // 3 because we need at least k items for each of the 3 types
    max_k = N // 3

    # Iterate k from max_k down to 0
