    solve()

class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        # Step 1: Count frequencies of each character
        counts = Counter(s)
        # Get distinct counts present in the string
        distinct_counts = sorted(counts.values())

        # We also consider k=1 if it's not present, as it might be optimal
        if 1 not in distinct_counts:
            distinct_counts.append(1)

        min_ops = float('inf')
        n = len(s)

        # Map char index (0-25) to its count
        char_counts = [0] * 26
        for char, count in counts.items():
            char_counts[ord(char) - ord('a')] = count

        for k in distinct_counts:
            # DP: dp[balance] = min_cost
            # balance can be positive or negative. We use a dict.
            # Initial state: balance 0, cost 0
            dp = {0: 0}

            for i in range(26):
                c = char_counts[i]
                if c == 0:
                    continue

                # Determine possible nets for this character
                # If c > k: must keep -> net = c - k (surplus)
                # If c == k: net = 0 (neutral)
                # If c < k: choice -> net1 = c - k (deficit), net2 = c (surplus)

                if c > k:
                    nets = [c - k]
                elif c == k:
                    nets = [0]
                else:
                    nets = [c - k, c]

                new_dp = {}
                for b, cost in dp.items():
                    for net in nets:
                        # Calculate potential moves between current balance and current net
                        # A move saves 1 operation (change vs delete+insert)
                        moves = 0
                        if b > 0 and net < 0:
                            moves = min(b, -net)
                        elif b < 0 and net > 0:
                            moves = min(-b, net)

                        # Cost contribution: |net| (base cost) - moves (savings)
                        new_cost = cost + abs(net) - moves
                        new_balance = b + net - moves

                        if new_balance not in new_dp or new_dp[new_balance] > new_cost:
                            new_dp[new_balance] = new_cost
                dp = new_dp

            # After processing all chars, any remaining balance must be resolved by deletions/insertions
            if dp:
                final_cost = min(abs(b) + cost for b, cost in dp.items())
                if final_cost < min_ops:
                    min_ops = final_cost

        return min_ops

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Step 1: Identify numbers greater than threshold.
        # These numbers cannot form any edges because lcm(a, b) >= max(a, b).
        # Each such number is its own connected component.
        greater_count = 0
        for x in nums:
            if x > threshold:
                greater_count += 1

        # Step 2: Filter numbers <= threshold and store their indices for DSU.
        small_nums = [x for x in nums if x <= threshold]
        val_to_idx = {val: i for i, val in enumerate(small_nums)}
        n_small = len(small_nums)

        # Step 3: Initialize DSU for the small numbers.
        parent = list(range(n_small))
        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        # Step 4: Precompute divisors for all numbers from 1 to threshold using a sieve-like method.
        # We create a list where divisors[j] contains all divisors of j.
        divisors = [[] for _ in range(threshold + 1)]
        for i in range(1, threshold + 1):
            for j in range(i, threshold + 1, i):
                divisors[j].append(i)

        # Step 5: Iterate through each number L from 1 to threshold.
        # If L exists in nums, retrieve its precomputed divisors.
        # For each divisor d of L, if d also exists in nums, union the sets containing L and d.
        # This connects L with all its divisors present in the array.
        # Since lcm(d, L) = L (because d divides L) and L <= threshold, the edge condition is satisfied.
        for L in range(1, threshold + 1):
            if L in val_to_idx:
                for d in divisors[L]:
                    if d in val_to_idx:
                        union(val_to_idx[d], val_to_idx[L])

        # Step 6: Count connected components among small numbers.
        roots = set()
        for i in range(n_small):
            roots.add(find(i))
        small_components = len(roots)

        # Total components = components from small numbers + isolated large numbers
        return small_components + greater_count
